#!/usr/bin/env python3
"""Run the exact-build RDF4J writer and public recovery oracle on volatile NBD."""
# Some portions generated by Codex
from __future__ import annotations

import argparse
import json
import os
from pathlib import Path
import signal
import subprocess
import sys
from typing import Any

from runner_common import (
    add_seed_iso_builder_argument,
    backend_control,
    build_artifact_manifest,
    copy_and_hash,
    copy_file_exclusive,
    create_fresh_directory,
    create_qcow_overlay,
    create_seed_iso,
    fence_nbd_then_stop_guest,
    guest_classpath,
    guest_qemu_arguments,
    require_executable,
    require_free_tcp_ports,
    require_regular_file,
    resolve_seed_iso_builder,
    sha256_file,
    start_backend,
    start_logged_process,
    stop_process,
    wait_for_path,
    write_json_exclusive,
    write_text_exclusive,
)

SCRIPT_DIR = Path(__file__).resolve().parent
GUEST_DIR = SCRIPT_DIR / "guest"
DATA_BYTES = 128 * 1024 * 1024
FAILURE_MARKERS = (
    "actual-writer-failed",
    "actual-writer-setup-failed",
    "actual-recovery-failed",
)


def parse_args() -> argparse.Namespace:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--scratch-root", required=True, type=Path,
                        help="new, non-existing directory for all images and logs")
    parser.add_argument("--repo-root", required=True, type=Path,
                        help="RDF4J checkout containing target/classes, target/test-classes, and .m2_repo")
    parser.add_argument("--host-classpath-file", required=True, type=Path,
                        help="one-line host classpath captured from the exact compiled LMDB test build")
    parser.add_argument("--os-base-image", required=True, type=Path,
                        help="provisioned Ubuntu guest qcow2 with Java 25, javac, Python 3, and ext4 tools")
    parser.add_argument("--firmware-code", required=True, type=Path,
                        help="read-only UEFI code image")
    parser.add_argument("--firmware-vars-template", required=True, type=Path,
                        help="disposable UEFI vars template; copied into the new scratch root")
    parser.add_argument("--qemu", required=True, type=Path, help="QEMU system emulator executable")
    parser.add_argument("--qemu-img", required=True, type=Path, help="qemu-img executable")
    add_seed_iso_builder_argument(parser)
    parser.add_argument("--port-base", required=True, type=int,
                        help="available localhost TCP port; recovery uses the next port")
    parser.add_argument("--machine", choices=("virt", "q35"), default="virt")
    parser.add_argument("--accel", default="hvf", help="QEMU accelerator (default: hvf)")
    parser.add_argument("--cpu", default="host", help="QEMU CPU model (default: host)")
    parser.add_argument("--native-classifier", choices=("linux", "linux-arm64", "linux-ppc64le"),
                        default="linux-arm64", help="Linux LWJGL native classifier used by the guest")
    parser.add_argument("--smp", type=int, default=4)
    parser.add_argument("--memory-mib", type=int, default=4096)
    parser.add_argument("--writer-timeout-seconds", type=int, default=300)
    parser.add_argument("--recovery-timeout-seconds", type=int, default=300)
    parser.add_argument("--cut-seed", type=int, default=20260927)
    return parser.parse_args()


def validate_inputs(args: argparse.Namespace) -> dict[str, Any]:
    repo = args.repo_root.expanduser().resolve(strict=True)
    if not repo.is_dir():
        raise ValueError(f"repository root is not a directory: {repo}")
    if not (repo / ".m2_repo").is_dir():
        raise FileNotFoundError(f"missing workspace Maven repository: {repo / '.m2_repo'}")
    qemu = require_executable(args.qemu, "QEMU")
    qemu_img = require_executable(args.qemu_img, "qemu-img")
    seed_iso_tool, seed_iso_builder = resolve_seed_iso_builder(args)
    seed_iso_tool = require_executable(seed_iso_tool, seed_iso_builder)
    os_image = require_regular_file(args.os_base_image, "OS base image")
    firmware_code = require_regular_file(args.firmware_code, "UEFI code image")
    firmware_vars = require_regular_file(args.firmware_vars_template, "UEFI vars template")
    classpath = require_regular_file(args.host_classpath_file, "host classpath file")
    backend = require_regular_file(repo / "scripts/lmdb-crashlab/volatile_nbd.py", "checked-in NBD backend")
    artifact_manifest = build_artifact_manifest(repo)
    classpath_value, classpath_manifest = guest_classpath(
        classpath, repo, native_classifier=args.native_classifier)
    if not 1 <= args.port_base <= 65534:
        raise ValueError("--port-base must allow both it and its recovery successor in the TCP port range")
    require_free_tcp_ports("127.0.0.1", (args.port_base, args.port_base + 1))
    if args.smp < 1 or args.memory_mib < 1024:
        raise ValueError("guest must have at least one CPU and 1024 MiB RAM")
    if args.writer_timeout_seconds < 1 or args.recovery_timeout_seconds < 1:
        raise ValueError("guest timeouts must be positive")
    return {
        "repo_root": repo,
        "qemu": qemu,
        "qemu_img": qemu_img,
        "seed_iso_tool": seed_iso_tool,
        "seed_iso_builder": seed_iso_builder,
        "os_image": os_image,
        "firmware_code": firmware_code,
        "firmware_vars": firmware_vars,
        "classpath_file": classpath,
        "backend": backend,
        "artifact_manifest": artifact_manifest,
        "classpath_value": classpath_value,
        "classpath_manifest": classpath_manifest,
    }


def create_blank_image(path: Path, size: int) -> None:
    with path.open("xb") as stream:
        stream.truncate(size)
        stream.flush()
        os.fsync(stream.fileno())


def prepare_guest_inputs(root: Path, results: Path, qemu_root: Path, inputs: dict[str, Any],
                         args: argparse.Namespace) -> dict[str, Any]:
    for directory in (results, qemu_root, root / "nbd", root / "data"):
        directory.mkdir()
    classpath_copy = results / "actual-build-classpath-host.txt"
    copy_file_exclusive(inputs["classpath_file"], classpath_copy)
    write_text_exclusive(results / "actual-build-classpath-guest.txt",
                         inputs["classpath_value"] + "\n")
    write_json_exclusive(results / "actual-current-build-manifest.json", inputs["artifact_manifest"])
    write_json_exclusive(results / "actual-classpath-manifest.json", inputs["classpath_manifest"])
    image = root / "data/data.raw"
    create_blank_image(image, DATA_BYTES)

    writer_os = qemu_root / "writer-os.qcow2"
    recovery_os = qemu_root / "recovery-os.qcow2"
    create_qcow_overlay(inputs["qemu_img"], inputs["os_image"], writer_os,
                        qemu_root / "writer-os-overlay.log")
    create_qcow_overlay(inputs["qemu_img"], inputs["os_image"], recovery_os,
                        qemu_root / "recovery-os-overlay.log")
    writer_vars = qemu_root / "writer-vars.fd"
    recovery_vars = qemu_root / "recovery-vars.fd"
    copy_file_exclusive(inputs["firmware_vars"], writer_vars)
    copy_file_exclusive(inputs["firmware_vars"], recovery_vars)
    writer_seed = create_seed_iso(inputs["seed_iso_tool"], qemu_root, "writer", "boot-writer.sh",
                                  builder=inputs["seed_iso_builder"])
    recovery_seed = create_seed_iso(inputs["seed_iso_tool"], qemu_root, "recovery", "boot-recovery.sh",
                                    builder=inputs["seed_iso_builder"])

    sources = [inputs["backend"], GUEST_DIR / "Rdf4jCrashlabOracle.java",
               GUEST_DIR / "CrashPostBaselineWriterMain.java", GUEST_DIR / "writer-controller.py",
               GUEST_DIR / "boot-writer.sh", GUEST_DIR / "boot-recovery.sh",
               GUEST_DIR / "bootstrap-user-data.yaml.in"]
    source_hashes = [{"path": str(path), "sha256": sha256_file(path)} for path in sources]
    manifest = {
        "repo_root": str(inputs["repo_root"]),
        "os_base_image": str(inputs["os_image"]),
        "os_base_image_sha256": sha256_file(inputs["os_image"]),
        "firmware_code": str(inputs["firmware_code"]),
        "firmware_code_sha256": sha256_file(inputs["firmware_code"]),
        "firmware_vars_template": str(inputs["firmware_vars"]),
        "firmware_vars_template_sha256": sha256_file(inputs["firmware_vars"]),
        "checked_in_volatile_nbd_backend": str(inputs["backend"]),
        "checked_in_volatile_nbd_backend_sha256": sha256_file(inputs["backend"]),
        "source_files": source_hashes,
        "data_image": str(image),
        "data_image_size_bytes": DATA_BYTES,
        "data_image_initial_sha256": sha256_file(image),
        "qemu_writeback_with_flush_fua": True,
        "qemu_snapshot_or_unsafe_cache": False,
        "guest_repo_and_m2_shares_read_only": True,
        "writer_os_overlay": str(writer_os),
        "recovery_os_overlay": str(recovery_os),
        "writer_seed_iso": str(writer_seed),
        "recovery_seed_iso": str(recovery_seed),
        "guest_jdk_class_major": 69,
        "fault_claim_boundary": "QEMU Linux guest and volatile NBD device-loss simulation only; not physical host power loss.",
    }
    write_json_exclusive(results / "actual-campaign-input-manifest.json", manifest)
    return {"image": image, "writer_os": writer_os, "recovery_os": recovery_os,
            "writer_vars": writer_vars, "recovery_vars": recovery_vars,
            "writer_seed": writer_seed, "recovery_seed": recovery_seed,
            "source_hashes": {item["path"]: item["sha256"] for item in source_hashes}}


def qemu_command(inputs: dict[str, Any], args: argparse.Namespace, *, name: str, os_disk: Path,
                 vars_file: Path, port: int, seed: Path, serial: Path, results: Path) -> list[str]:
    return guest_qemu_arguments(qemu=inputs["qemu"], name=name, machine=args.machine,
                                accel=args.accel, cpu=args.cpu,
                                smp=args.smp, memory_mib=args.memory_mib,
                                firmware_code=inputs["firmware_code"], firmware_vars=vars_file,
                                os_disk=os_disk, data_port=port, seed_iso=seed, serial_log=serial,
                                repo_root=inputs["repo_root"], results=results)


def run_guest(command: list[str], results: Path, label: str) -> subprocess.Popen[bytes]:
    write_json_exclusive(results / f"actual-{label}-qemu-command.json", command)
    return start_logged_process(command, results / f"actual-{label}-qemu.log")


def read_events(path: Path) -> list[dict[str, Any]]:
    if not path.is_file():
        return []
    return [json.loads(line) for line in path.read_text(encoding="utf-8").splitlines() if line.strip()]


def main() -> int:
    args = parse_args()
    inputs = validate_inputs(args)
    root = create_fresh_directory(args.scratch_root)
    results = root / "results"
    qemu_root = root / "qemu"
    nbd_root = root / "nbd"
    paths = prepare_guest_inputs(root, results, qemu_root, inputs, args)
    backend_process = recovery_backend = writer_qemu = recovery_qemu = None
    backend_hash_before = sha256_file(inputs["backend"])
    os_hash_before = sha256_file(inputs["os_image"])
    classpath_hash_before = sha256_file(inputs["classpath_file"])
    run_error: BaseException | None = None
    report: dict[str, Any] | None = None
    try:
        writer_control = nbd_root / "writer-control.sock"
        writer_events = results / "actual-writer-nbd-events.jsonl"
        writer_backend_log = results / "actual-writer-backend.log"
        backend_process = start_backend(python=Path(sys.executable), backend=inputs["backend"],
                                        image=paths["image"], control=writer_control,
                                        port=args.port_base, events=writer_events,
                                        log=writer_backend_log,
                                        command_record=results / "actual-writer-backend-command.json")
        writer_status = backend_control(Path(sys.executable), inputs["backend"], writer_control, "status")
        write_json_exclusive(results / "actual-writer-backend-initial-status.json", writer_status)
        writer_args = qemu_command(inputs, args, name="rdf4j-crashlab-writer",
                                   os_disk=paths["writer_os"], vars_file=paths["writer_vars"],
                                   port=args.port_base, seed=paths["writer_seed"],
                                   serial=results / "actual-writer-serial.log", results=results)
        writer_qemu = run_guest(writer_args, results, "writer")
        marker = wait_for_path(writer_qemu,
                               [results / "actual-lmdb-final-ack",
                                results / "actual-writer-failed",
                                results / "actual-writer-setup-failed"],
                               args.writer_timeout_seconds)
        if marker.name != "actual-lmdb-final-ack":
            raise RuntimeError(f"writer guest failed: {marker.read_text(errors='replace')}")
        writer_status_before_cut = backend_control(Path(sys.executable), inputs["backend"],
                                                   writer_control, "status")
        write_json_exclusive(results / "actual-writer-backend-status-before-cut.json",
                             writer_status_before_cut)
        cut_report = fence_nbd_then_stop_guest(
            writer_qemu,
            lambda: backend_control(Path(sys.executable), inputs["backend"], writer_control,
                                    "cut", "--survival", "drop", "--seed", str(args.cut_seed)),
        )
        writer_qemu = None
        write_json_exclusive(results / "actual-nbd-device-cut.json", cut_report)
        preserved_dir = results / "pre-recovery-image"
        preserved_dir.mkdir()
        preserved_image = copy_and_hash(paths["image"], preserved_dir / "data.raw")
        preserved_witness = copy_and_hash(results / "actual-ack-witness.tsv",
                                          preserved_dir / "external-witness.tsv")
        preserved_namespace_witness = copy_and_hash(results / "actual-namespace-witness.tsv",
                                                    preserved_dir / "namespace-witness.tsv")
        stop_process(backend_process, signal.SIGINT)
        backend_process = None

        recovery_control = nbd_root / "recovery-control.sock"
        recovery_events = results / "actual-recovery-nbd-events.jsonl"
        recovery_backend_log = results / "actual-recovery-backend.log"
        recovery_backend = start_backend(python=Path(sys.executable), backend=inputs["backend"],
                                         image=paths["image"], control=recovery_control,
                                         port=args.port_base + 1, events=recovery_events,
                                         log=recovery_backend_log,
                                         command_record=results / "actual-recovery-backend-command.json")
        recovery_status = backend_control(Path(sys.executable), inputs["backend"], recovery_control,
                                          "status")
        write_json_exclusive(results / "actual-recovery-backend-initial-status.json", recovery_status)
        recovery_args = qemu_command(inputs, args, name="rdf4j-crashlab-recovery",
                                     os_disk=paths["recovery_os"], vars_file=paths["recovery_vars"],
                                     port=args.port_base + 1, seed=paths["recovery_seed"],
                                     serial=results / "actual-recovery-serial.log", results=results)
        recovery_qemu = run_guest(recovery_args, results, "recovery")
        recovery_marker = wait_for_path(recovery_qemu,
                                        [results / "actual-lmdb-recovery-done",
                                         results / "actual-recovery-failed"],
                                        args.recovery_timeout_seconds)
        if recovery_qemu.poll() is None:
            stop_process(recovery_qemu, signal.SIGKILL)
        recovery_qemu = None
        recovery_status_after = backend_control(Path(sys.executable), inputs["backend"],
                                                recovery_control, "status")
        write_json_exclusive(results / "actual-recovery-backend-status-after-oracle.json",
                             recovery_status_after)
        oracle_log = results / "actual-recovery-oracle.log"
        oracle_text = oracle_log.read_text(encoding="utf-8", errors="replace") if oracle_log.exists() else ""
        public_checks_completed = "PUBLIC_INDEX_CONTEXT_SPARQL_CHECKS=COMPLETED" in oracle_text
        findings = [line.removeprefix("FINDING=") for line in oracle_text.splitlines()
                    if line.startswith("FINDING=")]
        if recovery_marker.name == "actual-lmdb-recovery-done" and not findings:
            result = "PUBLIC_ORACLE_PASS"
        elif recovery_marker.name == "actual-recovery-failed" and public_checks_completed:
            result = "PUBLIC_ORACLE_COMPLETED_WITH_FINDINGS"
        else:
            result = "PUBLIC_ORACLE_INCOMPLETE"
        writer_events = read_events(writer_events)
        sync_events = [event for event in writer_events if event.get("event") in ("FLUSH_DONE", "FUA_DONE")]
        last_data_write = next((event for event in reversed(writer_events)
                                if event.get("event") == "WRITE"), None)
        last_sync = next((event for event in reversed(writer_events)
                          if event.get("event") in ("FLUSH_DONE", "FUA_DONE")), None)
        last_write_index = max((index for index, event in enumerate(writer_events)
                                if event.get("event") == "WRITE"), default=-1)
        last_sync_index = max((index for index, event in enumerate(writer_events)
                               if event.get("event") in ("FLUSH_DONE", "FUA_DONE")), default=-1)
        report = {
            "result": result,
            "scope": "exact compiled RDF4J LMDB writer and public recovery oracle on ext4 over checked-in volatile TCP NBD",
            "fault_model": "guest process was SIGKILLed after the namespace-only commit returned and an independent witness was fsynced; NBD cut dropped volatile sectors, then the backend restarted from the durable raw image; not physical host power loss",
            "acknowledged_baseline_transactions": 3,
            "retirement_cycle": "the same default-context value was deleted and re-added in separately acknowledged commits",
            "namespace_only_commit": "commit returned; witness was fsynced to the independent 9p share; no guest filesystem sync or orderly shutdown before the device cut",
            "checked_in_backend": str(inputs["backend"]),
            "checked_in_backend_sha256": backend_hash_before,
            "data_device_cut": cut_report,
            "writer_backend_status_before_cut": writer_status_before_cut,
            "recovery_backend_status_initial": recovery_status,
            "recovery_backend_status_after_oracle": recovery_status_after,
            "pre_recovery_image": preserved_image,
            "external_witness": preserved_witness,
            "namespace_witness": preserved_namespace_witness,
            "writer_backend_sync_event_count": len(sync_events),
            "writer_backend_flush_done_count": sum(event.get("event") == "FLUSH_DONE" for event in sync_events),
            "writer_backend_fua_done_count": sum(event.get("event") == "FUA_DONE" for event in sync_events),
            "last_data_write_before_cut": last_data_write,
            "last_successful_flush_or_fua_before_cut": last_sync,
            "last_data_write_followed_by_no_flush_or_fua": last_write_index > last_sync_index,
            "recovery_oracle_log": str(oracle_log),
            "recovery_oracle_findings": findings,
            "public_index_context_sparql_checks_completed": public_checks_completed,
            "guest_jdk_writer": (results / "actual-writer-java-version.txt").read_text(errors="replace"),
            "guest_jdk_recovery": (results / "actual-recovery-java-version.txt").read_text(errors="replace")
                if (results / "actual-recovery-java-version.txt").exists() else None,
            "current_build_manifest": str(results / "actual-current-build-manifest.json"),
            "boundary": "This measures QEMU Linux guest, ext4, and virtual NBD behavior only; it does not establish loss of the host kernel, APFS, SSD controller, device firmware cache, or physical Mac power.",
        }
    except BaseException as error:
        run_error = error
        failure_path = results / "actual-campaign-runner-failure.txt"
        if not failure_path.exists():
            try:
                write_text_exclusive(failure_path, type(error).__name__ + ": " + str(error) + "\n")
            except FileExistsError:
                pass
    finally:
        stop_process(writer_qemu, signal.SIGKILL)
        stop_process(recovery_qemu, signal.SIGKILL)
        stop_process(backend_process, signal.SIGINT)
        stop_process(recovery_backend, signal.SIGINT)

    input_hashes_after = {
        "backend": sha256_file(inputs["backend"]),
        "os_image": sha256_file(inputs["os_image"]),
        "classpath": sha256_file(inputs["classpath_file"]),
    }
    expected_input_hashes = {"backend": backend_hash_before, "os_image": os_hash_before,
                             "classpath": classpath_hash_before}
    source_hashes_after = {path: sha256_file(Path(path)) for path in paths["source_hashes"]}
    source_unchanged = source_hashes_after == paths["source_hashes"]
    try:
        build_manifest_after = build_artifact_manifest(inputs["repo_root"])
        compiled_artifacts_unchanged = build_manifest_after == inputs["artifact_manifest"]
    except (FileNotFoundError, ValueError):
        build_manifest_after = None
        compiled_artifacts_unchanged = False
    try:
        _, classpath_manifest_after = guest_classpath(
            inputs["classpath_file"], inputs["repo_root"], native_classifier=args.native_classifier)
        classpath_artifacts_unchanged = classpath_manifest_after == inputs["classpath_manifest"]
    except (FileNotFoundError, ValueError):
        classpath_artifacts_unchanged = False
    if (input_hashes_after != expected_input_hashes or not source_unchanged or
            not compiled_artifacts_unchanged or not classpath_artifacts_unchanged):
        mutation_error = RuntimeError("a read-only source input changed during the campaign")
        if run_error is None:
            run_error = mutation_error
    if run_error is not None:
        failure_path = results / "actual-campaign-runner-failure.txt"
        if not failure_path.exists():
            write_text_exclusive(failure_path, type(run_error).__name__ + ": " + str(run_error) + "\n")
        raise run_error
    assert report is not None
    report["read_only_source_inputs_unchanged"] = source_unchanged
    report["compiled_artifacts_unchanged"] = compiled_artifacts_unchanged
    report["classpath_artifacts_unchanged"] = classpath_artifacts_unchanged
    report["os_base_image_unchanged"] = input_hashes_after["os_image"] == os_hash_before
    report["classpath_file_unchanged"] = input_hashes_after["classpath"] == classpath_hash_before
    report["backend_source_unchanged"] = input_hashes_after["backend"] == backend_hash_before
    report["pre_recovery_image_sha256_after_run"] = sha256_file(results / "pre-recovery-image/data.raw")
    report["working_image_sha256_after_recovery"] = sha256_file(paths["image"])
    write_json_exclusive(results / "actual-campaign-report.json", report)
    print(json.dumps(report, indent=2, sort_keys=True))
    if report["result"] == "PUBLIC_ORACLE_PASS":
        return 0
    return 2 if report["result"] == "PUBLIC_ORACLE_COMPLETED_WITH_FINDINGS" else 3


if __name__ == "__main__":
    raise SystemExit(main())
